/** The text/plain answers tus gives. */
function text(description: string, example: string) {
  return {
    description,
    content: { "text/plain": { schema: { type: "string" }, example } },
  };
}

/** The JSON answers the upload mount gives, outside tus. */
function json(description: string, example: Record<string, unknown>) {
  return {
    description,
    content: { "application/json": { schema: ERROR_DOC, example } },
  };
}

const TUS_RESUMABLE = {
  type: "string",
  enum: ["1.0.0"],
  description: "The tus protocol version; always 1.0.0",
  examples: ["1.0.0"],
};

const UPLOAD_ID_PARAM = {
  type: "object",
  properties: {
    id: {
      type: "string",
      description: "The upload's id: the last segment of the Location that POST /uploads answered",
      examples: [EXAMPLE_IDS.upload],
    },
  },
  required: ["id"],
};

// What an upload's address answers once the upload is over, said once here
// so HEAD and PATCH agree (issues #276, #277), and docs/api.md's upload
// status table repeats these words exactly (test/api/openapi.test.ts):
// - the hourly sweep deletes an upload untouched for 24 hours, and an
//   ingested upload's kept info file 24 hours after the ingest, data and
//   info file both, so the address then answers 404, never 410;
// - a finish whose import cannot be queued removes the upload too (404 after);
// - HEAD answers 410 only after an import that failed with nothing saved (an
//   imported upload answers 200, finished); PATCH answers 410 after any
//   import, since its store sees the data file gone either way.
const UPLOAD_404 =
  "No such upload: the id is unknown, the upload was removed after 24 hours untouched (or 24 " +
  "hours after its import), or it was removed because its import could not be queued";
const RESEND_UNLESS_FILE =
  "send the file again as a new upload, unless that reason is about the file itself (an " +
  "unsupported type, or a duplicate under duplicates skip)";
const HEAD_410 =
  "The import failed and nothing was saved. GET /uploads/{id}/result says why; " +
  RESEND_UNLESS_FILE;
const PATCH_410 =
  "The upload is over: it was imported, or its import failed with nothing saved. GET " +
  `/uploads/{id}/result says which; if it failed, ${RESEND_UNLESS_FILE}`;
const QUEUE_FAILED =
  "the last byte arrived but the import could not be queued: nothing was saved and the " +
  "upload was removed, so send the file again as a new upload";

const TUS_412 = text("The Tus-Resumable header is missing", "Tus-Resumable Required\n");
const TUS_500 = text(
  "Something unexpected went wrong while handling the bytes. If the upload has an address, " +
    "ask HEAD where to carry on; if not, start again.",
  "Something went wrong with that request\n",
);
const UNAUTHORIZED_RESPONSE = {
  description: UNAUTHORIZED_DOC.description,
  headers: UNAUTHORIZED_DOC.headers,
  content: {
    "application/json": {
      schema: {
        type: "object",
        properties: UNAUTHORIZED_DOC.properties,
        required: UNAUTHORIZED_DOC.required,
      },
      example: { error: "unauthorized" },
    },
  },
};

/** The tus upload routes' operations, by method and path (Public API v1 contract). */
const TUS_DOCS: Record<string, FastifySchema> = {
  [`POST ${API_PREFIX}/uploads`]: {
    summary: "Start an upload",
    description:
      "Creates a resumable upload of a known size (tus 1.0.0 creation). The size goes in " +
      "Upload-Length, at most 536870912 bytes (512 MiB). Upload-Metadata must carry filename, " +
      "whose extension says what the file is: .3mf, .stl, .step, .stp or .scad. Add modelId " +
      "to put the file into an existing model, or batch (and combine) to group several " +
      "uploads; with neither, the file becomes a model of its own, named after the file.\n\n" +
      "duplicates says what happens when a live model already holds a file with the same " +
      "SHA-256: allow (the default) stores it anyway and the result lists the copies; skip " +
      "stores nothing and the result is failed with code duplicate. A file in the trash " +
      "never counts.\n\n" +
      "The answer's Location is the upload's address. Send the bytes there with PATCH, then " +
      "poll GET /uploads/{id}/result until it says done or failed. The body of this request " +
      "may already carry the first bytes, or the whole file, when it is sent with " +
      "Content-Type: application/offset+octet-stream (tus creation-with-upload).\n\n" +
      "Nothing is stored until the last byte arrives, and an upload left unfinished for 24 " +
      "hours is deleted.",
    tags: ["Uploads"],
    operationId: "createUpload",
    headers: {
      type: "object",
      properties: {
        "tus-resumable": TUS_RESUMABLE,
        "upload-length": {
          type: "integer",
          minimum: 0,
          maximum: 536870912,
          description: "The file's size in bytes, at most 536870912",
          examples: [5242880],
        },
        "upload-metadata": {
          type: "string",
          description:
            "tus Upload-Metadata: comma-separated pairs, each a key, a space and the value in " +
            "base64. filename is required. modelId adds the file to that live model. batch " +
            "(1 to 200 characters) groups the uploads that share it; with combine 1 or true " +
            "they become one model, with combine 0, false or left out each is its own model. " +
            "modelId cannot be sent with batch or combine. duplicates is skip or allow, allow " +
            "when left out. Other keys are ignored.",
          examples: [
            "filename Y2FibGUtY2xpcC4zbWY=,modelId " +
              "MDE5M2E1YzItN2Q0ZS03YjIxLTlmMDAtM2M1YTFlMmI0ZDZm",
          ],
        },
      },
      required: ["tus-resumable", "upload-length", "upload-metadata"],
    },
    response: {
      201: {
        description:
          "Created. Location is the upload's address, /api/v1/uploads/{id}; send the bytes " +
          "there. With creation-with-upload, Upload-Offset says how many bytes were taken.",
        headers: {
          Location: {
            type: "string",
            description: "The upload's address, relative to the server",
            example: `/api/v1/uploads/${EXAMPLE_IDS.upload}`,
          },
          "Tus-Resumable": { type: "string", description: "1.0.0" },
          "Upload-Offset": {
            type: "integer",
            description: "Bytes taken so far, with creation-with-upload",
          },
        },
        type: "null",
      },
      400: text(
        "Upload-Length is missing, or Upload-Metadata is malformed, has no filename, has a " +
          "duplicates other than skip or allow, or breaks a rule above. The body says which.",
        "Upload-Metadata must carry the file's name as filename\n",
      ),
      401: UNAUTHORIZED_RESPONSE,
      404: json("modelId names no live model: unknown, or in the trash", { error: "not_found" }),
      412: TUS_412,
      413: text("Upload-Length is over 536870912 bytes", "Maximum size exceeded\n"),
      415: text(
        "The file name's extension is not one Platehouse takes",
        "This file is not a supported .3mf, .stl, .step, .stp or .scad file; nothing was saved\n",
      ),
      500: TUS_500,
      501: text(
        "A tus extension Platehouse does not offer: Upload-Defer-Length or Upload-Concat",
        "creation-defer-length extension is not (yet) supported.\n",
      ),
      503: {
        description:
          "JSON: the model named by modelId, or the token, could not be checked (the " +
          "database is unreachable); try again. Text: a creation that carried the whole " +
          `file, where ${QUEUE_FAILED}`,
        content: {
          "application/json": { schema: ERROR_DOC, example: { error: "unavailable" } },
          "text/plain": {
            schema: { type: "string" },
            example: "The upload could not be queued; nothing was saved. Try again.\n",
          },
        },
      },
    },
  },
  [`HEAD ${API_PREFIX}/uploads/:id`]: {
    summary: "Where to resume an upload",
    description:
      "Upload-Offset says how many bytes have arrived; send the rest with PATCH from there. " +
      "Use it after a cut-off, such as a network change. Once the file has been imported, " +
      "Upload-Offset equals Upload-Length, so nothing is sent again. If the import failed " +
      "with nothing saved, the answer is 410, and GET /uploads/{id}/result says why. An " +
      "upload removed by the 24-hour sweep, or because its import could not be queued, is " +
      "404.",
    tags: ["Uploads"],
    operationId: "resumeUpload",
    headers: {
      type: "object",
      properties: { "tus-resumable": TUS_RESUMABLE },
      required: ["tus-resumable"],
    },
    params: UPLOAD_ID_PARAM,
    response: {
      200: {
        description: "Upload-Offset and Upload-Length; no body",
        headers: {
          "Upload-Offset": { type: "integer", description: "Bytes received" },
          "Upload-Length": { type: "integer", description: "The upload's size" },
        },
        type: "null",
      },
      401: {
        description: UNAUTHORIZED_DOC.description,
        headers: UNAUTHORIZED_DOC.headers,
        type: "null",
      },
      404: { description: UPLOAD_404, type: "null" },
      410: { description: HEAD_410, type: "null" },
      412: { description: "The Tus-Resumable header is missing", type: "null" },
      500: { description: "Something unexpected went wrong", type: "null" },
      503: { description: UNAVAILABLE_DOC.description, type: "null" },
    },
  },
  [`PATCH ${API_PREFIX}/uploads/:id`]: {
    summary: "Send an upload's bytes",
    description:
      "Appends the request body to the upload at Upload-Offset, which must equal the bytes " +
      "received so far (0 for the first request). One PATCH may carry the whole file, as " +
      "curl does, or the file may be sent in chunks of any size, each starting where the " +
      "last ended. After a cut-off, ask HEAD /uploads/{id} for the offset and carry on.\n\n" +
      "When the last byte lands, the file is queued for import; read " +
      "GET /uploads/{id}/result for the outcome. A single request may take up to about 72 " +
      "minutes, enough for 512 MiB at 1 Mbit/s.",
    tags: ["Uploads"],
    operationId: "sendUploadBytes",
    consumes: ["application/offset+octet-stream"],
    headers: {
      type: "object",
      properties: {
        "tus-resumable": TUS_RESUMABLE,
        "upload-offset": {
          type: "integer",
          minimum: 0,
          description: "Where this body starts: the bytes received so far",
          examples: [0],
        },
        "content-type": {
          type: "string",
          enum: ["application/offset+octet-stream"],
          description: "Always application/offset+octet-stream",
          examples: ["application/offset+octet-stream"],
        },
      },
      required: ["tus-resumable", "upload-offset", "content-type"],
    },
    params: UPLOAD_ID_PARAM,
    body: {
      type: "string",
      format: "binary",
      description: "The file's bytes from Upload-Offset on: all of them, or the next chunk",
    },
    response: {
      204: {
        description: "Taken; Upload-Offset is the new offset",
        headers: {
          "Upload-Offset": { type: "integer", description: "Bytes received, this body included" },
        },
        type: "null",
      },
      400: text("A tus header is malformed", "Invalid upload-offset\n"),
      401: UNAUTHORIZED_RESPONSE,
      403: text(
        "Upload-Offset or the Content-Type application/offset+octet-stream is missing",
        "Content-Type header required\n",
      ),
      404: text(UPLOAD_404, "The file for this url was not found\n"),
      409: text(
        "Upload-Offset is not the number of bytes received; ask HEAD for it",
        "Upload-Offset conflict\n",
      ),
      410: text(PATCH_410, "The file for this url no longer exists\n"),
      412: TUS_412,
      413: text("The body runs past Upload-Length", "upload's size exceeded\n"),
      500: TUS_500,
      503: {
        description:
          `Text: ${QUEUE_FAILED}. JSON: the token could not be checked (the database is ` +
          "unreachable); try again.",
        content: {
          "text/plain": {
            schema: { type: "string" },
            example: "The upload could not be queued; nothing was saved. Try again.\n",
          },
          "application/json": { schema: ERROR_DOC, example: { error: "unavailable" } },
        },
      },
    },
  },
  [`GET ${API_PREFIX}/uploads/:id/result`]: {
    summary: "What became of an upload",
    description:
      "pending while the upload is still arriving or being imported; done with the model " +
      "and file it made or joined; failed with a sentence saying why. Poll every second or " +
      "two until it is not pending. A result is kept for 24 hours.",
    tags: ["Uploads"],
    operationId: "getUploadResult",
    params: UPLOAD_ID_PARAM,
    response: {
      200: {
        description:
          "The upload's state. pending while it is arriving or being imported; done with the " +
          "model and file, and duplicates: the files of live models that already held the same " +
          "bytes (empty when none did); or failed with a message. A duplicate refused under " +
          "duplicates skip is failed with code duplicate and the duplicates it matched, so the " +
          "client can point at the model or send the file again with duplicates allow. Other " +
          "failures carry no code.",
        content: {
          "application/json": {
            schema: {
              type: "object",
              properties: {
                status: { type: "string", enum: ["pending", "done", "failed"] },
                modelId: { type: "string", description: "With done: the model" },
                fileId: { type: "string", description: "With done: the new file" },
                error: { type: "string", description: "With failed: why, in a sentence" },
                code: {
                  type: "string",
                  enum: ["duplicate"],
                  description: "With failed: duplicate when a duplicate was skipped; else absent",
                },
                duplicates: {
                  type: "array",
                  description:
                    "With done, and with failed code duplicate: the live files that already " +
                    "held the same bytes, oldest first, at most 10. A file in a trashed model " +
                    "is never listed.",
                  items: {
                    type: "object",
                    properties: {
                      modelId: { type: "string" },
                      modelName: { type: "string" },
                      fileId: { type: "string" },
                      fileName: { type: "string" },
                    },
                    required: ["modelId", "modelName", "fileId", "fileName"],
                  },
                },
              },
              required: ["status"],
            },
            examples: {
              done: {
                summary: "Imported",
                value: {
                  status: "done",
                  modelId: EXAMPLE_IDS.model,
                  fileId: EXAMPLE_IDS.file,
                  duplicates: [],
                },
              },
              pending: { summary: "Still arriving or importing", value: { status: "pending" } },
              duplicate: {
                summary: "Skipped: already in the library (duplicates skip)",
                value: {
                  status: "failed",
                  error:
                    `This file is already in the library, in the model "Cable clip" ` +
                    `(id ${EXAMPLE_IDS.model}), so it was skipped; nothing was saved`,
                  code: "duplicate",
                  duplicates: [
                    {
                      modelId: EXAMPLE_IDS.model,
                      modelName: "Cable clip",
                      fileId: EXAMPLE_IDS.file,
                      fileName: "cable-clip.3mf",
                    },
                  ],
                },
              },
              failed: {
                summary: "Not imported",
                value: {
                  status: "failed",
                  error:
                    "This file is not a supported .3mf, .stl, .step, .stp or .scad file; nothing was saved",
                },
              },
            },
          },
        },
      },
      401: UNAUTHORIZED_RESPONSE,
      404: json("No such upload, or its result is more than 24 hours old", {
        error: "not_found",
      }),
      500: json(INTERNAL_DOC.description, { error: "internal" }),
      503: json("The result cannot be read right now; try again shortly", {
        error: "unavailable",
        message: "The upload's result cannot be read right now. Try again shortly.",
      }),
    },
  },
};

/**
 * The path a route is documented at: its URL without a trailing slash, so
 * the two routes Fastify registers for a prefixed "/" (POST /api/v1/uploads
 * and POST /api/v1/uploads/) are one operation.
 */
export function documentedUrl(url: string): string {
  return url.length > 1 ? url.replace(/\/+$/, "") : url;
}

/** A copy of value with every subschema carrying the PLATE_NUMBERS marker swapped for the doc. */
function withPlateNumbers(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(withPlateNumbers);
  if (value === null || typeof value !== "object") return value;
  if (Object.hasOwn(value, PLATE_NUMBERS)) return structuredClone(PLATE_NUMBERS_DOC);
  return Object.fromEntries(
    Object.entries(value).map(([key, inner]) => [key, withPlateNumbers(inner)]),
  );
}

/**
 * A HEAD that Fastify answers for a GET route: the GET's documentation, said
 * to be headers only, with every answer's body taken off and its headers
 * kept (Content-Length and Content-Disposition on a file's bytes,
 * WWW-Authenticate on the 401; issue #261). HEAD gets its own operationId
 * from @fastify/swagger (the GET's with -head).
 */
function headOnly(get: FastifySchema): FastifySchema {
  const doc = get as FastifySchema & {
    summary?: string;
    description?: string;
    response?: Record<string, { description?: string; headers?: unknown }>;
  };
  const response = Object.fromEntries(
    Object.entries(doc.response ?? {}).map(([code, answer]) => [
      code,
      {
        description: answer.description ?? "",
        ...(answer.headers === undefined ? {} : { headers: answer.headers }),
        type: "null",
      },
    ]),
  );
  return {
    ...doc,
    summary: `${doc.summary ?? ""} (headers only)`,
    description: `The same status and headers as the GET, with no body. ${doc.description ?? ""}`,
    response,
  } as FastifySchema;
}

/**
 * The router's answer to a path parameter over its maxParamLength (100, not
 * changed in app.ts), measured after percent-decoding. It comes before any
 * hook or route, so before the token is read and before a route's own
 * validation: a tag or collection name over 100 characters is this 414,
 * never a 400. app.ts frameworkError writes it in Fastify's own shape.
 */
export const PARAM_TOO_LONG_DOC = {
  description:
    "A path parameter is over 100 characters once percent-decoded. The server answers " +
    "this before it reads the token, in its own error shape rather than the API's.",
  type: "object",
  properties: {
    error: { type: "string", enum: ["URI Too Long"] },
    code: { type: "string", enum: ["FST_ERR_MAX_PARAM_LENGTH"] },
    statusCode: { type: "integer", enum: [414] },
  },
  required: ["error", "code", "statusCode"],
  examples: [{ error: "URI Too Long", code: "FST_ERR_MAX_PARAM_LENGTH", statusCode: 414 }],
} as const;

/**
 * The schema with the 414 added when the route's path has a parameter. Only
 * the document gains it: the route's own schema, which Fastify serializes
 * with, is never changed, and the 414 never reaches a route anyway.
 */
function withParamLimit(url: string, schema: FastifySchema): FastifySchema {
  if (!/\/:[A-Za-z0-9_]+/.test(url)) return schema;
  const doc = schema as FastifySchema & { response?: Record<string, unknown> };
  return { ...doc, response: { ...doc.response, 414: PARAM_TOO_LONG_DOC } } as FastifySchema;
}

/**
 * What the document says of one route: hidden unless it is under /api/v1/,
 * the tus routes' own description, or the route's schema as registered; with
 * the 414 on a route with a path parameter (withParamLimit).
 */
export function describeRoute(
  method: string,
  url: string,
  schema: FastifySchema | undefined,
): FastifySchema {
  const own = schema ?? {};
  if (!url.startsWith(`${API_PREFIX}/`)) return { ...own, hide: true };
  const pattern = documentedUrl(url).replace(/\(.*$/, "");
  const tus =
    TUS_DOCS[`${method} ${pattern}`] ??
    (method === "HEAD" ? TUS_DOCS[`GET ${pattern}`] : undefined);
  if (tus !== undefined) {
    const limited = withParamLimit(pattern, tus);
    if (method !== "HEAD" || TUS_DOCS[`HEAD ${pattern}`] !== undefined) return limited;
    // The tus routes have no schema, so @fastify/swagger cannot give their
    // HEAD its -head operationId as it does a v1 route's; it is set here.
    const { operationId } = tus as { operationId?: string };
    return { ...headOnly(limited), operationId: `${operationId}-head` } as FastifySchema;
  }
  const documented = withParamLimit(pattern, withPlateNumbers(own) as FastifySchema);
  // Fastify answers HEAD for every GET route with the GET's schema.
  return method === "HEAD" ? headOnly(documented) : documented;
}

/** Registers the document's generator on the root app; call it before any route. */
export async function registerOpenApi(
  app: FastifyInstance,
  opts: { serverUrl: string },
): Promise<void> {
  await app.register(fastifySwagger, {
    openapi: {
      openapi: "3.0.3",
      info: {
        title: "Platehouse API",
        version: "1.0.0",
        description:
          "The Platehouse public API, for scripts and tools such as AI coding assistants: upload " +
          "files, search the library, read models, files, plates and their print estimates, " +
          "and add or remove tags and collection memberships.\n\n" +
          "It never deletes, trashes or purges anything, and a model in the trash is " +
          "invisible to it.\n\n" +
          "Every request needs an API token, made in Settings, sent as " +
          "Authorization: Bearer <token>. Cookies are ignored, and no answer carries CORS " +
          "headers, so a web page on another site cannot call it.\n\n" +
          "Errors answer JSON with an error code word and, often, a message sentence. JSON " +
          "bodies are at most 1 MiB; uploads are at most 512 MiB. The guide is docs/api.md " +
          "in the Platehouse repository.",
      },
      servers: [{ url: opts.serverUrl, description: "This Platehouse server" }],
      tags: API_TAGS.map((tag) => ({ ...tag })),
      components: {
        securitySchemes: {
          bearer: {
            type: "http",
            scheme: "bearer",
            bearerFormat: "ph_ token",
            description:
              "An API token, made in Settings > API tokens and shown once. It starts with " +
              "ph_. Send it on every request as Authorization: Bearer <token>. Revoking it " +
              "in Settings stops it at once and leaves other tokens working.",
          },
        },
      },
      security: [{ bearer: [] }],
    },
    exposeHeadRoutes: true,
    transform: ({ schema, url, route }) => {
      const methods = Array.isArray(route.method) ? route.method : [route.method];
      return { schema: describeRoute(String(methods[0]), url, schema), url: documentedUrl(url) };
    },
  });
}
